def recover(A, bad=2):
    n=A.shape[0]; A=A.copy()
    def orbit(i,j):
        return {(i,j),(i,n-1-j),(n-1-i,j),(n-1-i,n-1-j),(j,i),(n-1-j,i),(j,n-1-i),(n-1-j,n-1-i)}
    # fix overlay cells using non-2 orbit values
    vals={}
    for i in range(n):
        for j in range(n):
            if A[i][j]==bad:
                cand=[A[a][b] for a,b in orbit(i,j) if A[a][b]!=bad]
                if cand:
                    vals[(i,j)]=Counter(cand).most_common(1)[0][0]
    for (i,j),v in vals.items(): A[i][j]=v
    return A
R=recover(DIn)
print(np.array_equal(R,DOu))
