def solve(A):
    n=len(A); A=np.array(A)
    def orbit(i,j):
        return [(i,j),(i,n-1-j),(n-1-i,j),(n-1-i,n-1-j),(j,i),(n-1-j,i),(j,n-1-i),(n-1-j,n-1-i)]
    out=A.copy()
    for i in range(n):
        for j in range(n):
            ov=[A[a][b] for a,b in orbit(i,j)]
            if len(set(ov))>1:
                out[i][j]=Counter(ov).most_common(1)[0][0]
    return out
